CREATE TABLE experiences(id TEXT PRIMARY KEY,card_id TEXT NOT NULL UNIQUE REFERENCES cards(id),title TEXT NOT NULL,mode TEXT NOT NULL,current_artifact_id TEXT,freshness TEXT NOT NULL DEFAULT 'current',archived INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE experience_contexts(id TEXT PRIMARY KEY,canonical_pack TEXT NOT NULL,content_fingerprint TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE experience_quotes(id TEXT PRIMARY KEY,card_id TEXT NOT NULL REFERENCES cards(id),context_id TEXT NOT NULL REFERENCES experience_contexts(id),model_config_fingerprint TEXT NOT NULL,purpose TEXT NOT NULL,budget_policy TEXT NOT NULL,estimated_tokens TEXT NOT NULL,expires_at TEXT NOT NULL,base_artifact_id TEXT,blocked_reason TEXT);
CREATE TABLE experience_grants(id TEXT PRIMARY KEY,quote_id TEXT NOT NULL UNIQUE REFERENCES experience_quotes(id),human_actor TEXT NOT NULL,budget_policy TEXT NOT NULL,issued_at TEXT NOT NULL,idempotency_key TEXT NOT NULL UNIQUE);
CREATE TABLE experience_runs(id TEXT PRIMARY KEY,experience_id TEXT NOT NULL REFERENCES experiences(id),grant_id TEXT NOT NULL REFERENCES experience_grants(id),job_id TEXT NOT NULL UNIQUE REFERENCES jobs(id),base_artifact_id TEXT,status TEXT NOT NULL,checkpoint TEXT NOT NULL DEFAULT '{}',revision_counter INTEGER NOT NULL DEFAULT 0,error_code TEXT,cancel_requested INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX experience_active_run ON experience_runs(experience_id) WHERE status IN ('queued','planning','generating','compiling','validating','repairing','cancel_requested','recovery_required','usage_unconfirmed');
CREATE TABLE generation_calls(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES experience_runs(id),phase TEXT NOT NULL,attempt INTEGER NOT NULL,status TEXT NOT NULL,input_reserved INTEGER NOT NULL,output_reserved INTEGER NOT NULL,actual_usage TEXT,response_bytes BLOB,response_sha256 TEXT,idempotency_key TEXT NOT NULL,started_at TEXT NOT NULL,finished_at TEXT,UNIQUE(run_id,phase,attempt));
CREATE TABLE experience_artifacts(id TEXT PRIMARY KEY,experience_id TEXT NOT NULL REFERENCES experiences(id),version INTEGER NOT NULL,context_id TEXT NOT NULL REFERENCES experience_contexts(id),run_id TEXT REFERENCES experience_runs(id),author_type TEXT NOT NULL,schema_version TEXT NOT NULL,sdk_version TEXT NOT NULL,runtime_hash TEXT NOT NULL,manifest TEXT NOT NULL,validation_report TEXT NOT NULL,artifact_hash TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(experience_id,version));
CREATE TABLE experience_files(id TEXT PRIMARY KEY,artifact_id TEXT NOT NULL REFERENCES experience_artifacts(id),path TEXT NOT NULL,mime TEXT NOT NULL,sha256 TEXT NOT NULL,bytes BLOB NOT NULL,UNIQUE(artifact_id,path));
CREATE TABLE experience_states(artifact_id TEXT NOT NULL REFERENCES experience_artifacts(id),local_session_id TEXT NOT NULL,state_schema_version TEXT NOT NULL,snapshot TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(artifact_id,local_session_id));
CREATE INDEX experience_run_recent ON experience_runs(experience_id,created_at DESC);
CREATE INDEX experience_card ON experiences(card_id);
CREATE INDEX experience_run_status ON experience_runs(status,created_at);
CREATE TRIGGER experience_context_immutable BEFORE UPDATE ON experience_contexts BEGIN SELECT RAISE(ABORT,'immutable context'); END;
CREATE TRIGGER experience_context_nodelete BEFORE DELETE ON experience_contexts BEGIN SELECT RAISE(ABORT,'immutable context'); END;
CREATE TRIGGER experience_artifact_immutable BEFORE UPDATE ON experience_artifacts BEGIN SELECT RAISE(ABORT,'immutable artifact'); END;
CREATE TRIGGER experience_artifact_nodelete BEFORE DELETE ON experience_artifacts BEGIN SELECT RAISE(ABORT,'immutable artifact'); END;
CREATE TRIGGER experience_file_immutable BEFORE UPDATE ON experience_files BEGIN SELECT RAISE(ABORT,'immutable file'); END;
CREATE TRIGGER experience_file_nodelete BEFORE DELETE ON experience_files BEGIN SELECT RAISE(ABORT,'immutable file'); END;
CREATE TRIGGER experience_grant_immutable BEFORE UPDATE ON experience_grants BEGIN SELECT RAISE(ABORT,'immutable grant'); END;
CREATE TRIGGER experience_quote_immutable BEFORE UPDATE ON experience_quotes BEGIN SELECT RAISE(ABORT,'immutable quote'); END;
